const item = $input.first().json;
const address = String(item.address || '').trim();
if (!address || address === '주소를 여기에 입력하세요') throw new Error('Analysis Input 노드에 분석 주소 한 곳을 입력해 주세요.');
return [{ json: { ...item, address } }];

const envelope = $input.first().json;
const input = $('Analysis Input').first().json;
const response = envelope && envelope.body && typeof envelope.body === 'object' ? envelope.body : envelope;
const statusCode = envelope && envelope.statusCode != null ? Number(envelope.statusCode) : null;
if (statusCode !== null && (!Number.isFinite(statusCode) || statusCode < 200 || statusCode >= 300)) throw new Error('Kakao address lookup failed with HTTP ' + statusCode + '.');
const matches = Array.isArray(response.documents) ? response.documents : [];
if (matches.length !== 1) throw new Error('Kakao 주소 검색 결과가 ' + matches.length + '건입니다. 정확히 한 곳으로 좁혀지는 주소를 입력해 주세요.');
const match = matches[0];
const latitude = Number(match.y);
const longitude = Number(match.x);
if (!Number.isFinite(latitude) || !Number.isFinite(longitude) || Math.abs(latitude) > 90 || Math.abs(longitude) > 180) throw new Error('주소 변환 결과의 좌표가 올바르지 않습니다.');
const normalized = match.road_address?.address_name || match.address?.address_name || match.address_name || input.address;
return [{ json: { request_id: input.request_id, address: input.address, normalized_address: normalized, latitude, longitude, geocode_match_count: matches.length, kakao_http_status: statusCode } }];

const envelope = $input.first().json;
const result = envelope && envelope.body && typeof envelope.body === 'object' ? envelope.body : envelope;
const statusCode = envelope && envelope.statusCode != null ? Number(envelope.statusCode) : null;
if (statusCode !== null && (!Number.isFinite(statusCode) || statusCode < 200 || statusCode >= 300)) throw new Error('Analyzer request failed with HTTP ' + statusCode + '.');
if (result.geocode_match_count !== 1) throw new Error('정확히 1건의 주소 매치가 확인되지 않아 분석 결과를 차단했습니다.');
if (result.status !== 'analysis_complete') throw new Error('분석이 완전히 끝나지 않았습니다. 결과를 고객에게 전달하지 마세요.');
if (result.publishable !== true || result.publication_gate !== 'passed') throw new Error('publication gate를 통과하지 못했습니다. 결과를 고객에게 전달하지 마세요.');
if (!result.coverage || result.coverage.category_count !== 247 || result.coverage.unclassified_category_count !== 0) throw new Error('247개 업종 전체 검증 또는 분류 완전성 조건을 충족하지 못했습니다.');
if (!Array.isArray(result.overall_top20) || result.overall_top20.length !== 20) throw new Error('전체 TOP20 결과가 완전하지 않습니다.');
if (!Array.isArray(result.a_top10) || result.a_top10.length !== 10) throw new Error('A형 TOP10 결과가 완전하지 않습니다.');
return [{ json: { ...result, analyzer_http_status: statusCode, operator_action: '고객 전달 검토 가능' } }];
